<script setup>
import { onMounted,ref,watch } from 'vue';
import { libraryRequest } from '../lib/library-client.js';
const props=defineProps({bookId:{type:String,required:true}}),provider=ref('vieneu'),voice=ref(''),text=ref('Xin chào. Đây là đoạn thử giọng ngắn cho audiobook của tôi.');
const catalog=ref(null),plan=ref(null),pending=ref(false),error=ref(''),requestId=ref(crypto.randomUUID());let generation=0;
async function load(){const current=++generation;pending.value=true;error.value='';plan.value=null;try{const result=await libraryRequest(`/${props.bookId}/voices?provider=${provider.value}`);if(current!==generation)return;catalog.value=result;voice.value=result.default_voice;}catch(e){if(current===generation)error.value=e.message;}finally{if(current===generation)pending.value=false;}}
watch(provider,load,{immediate:true});watch([voice,text],()=>{plan.value=null;requestId.value=crypto.randomUUID();});
onMounted(async()=>{try{const values=await libraryRequest(`/${props.bookId}/settings`);provider.value=values.effective.provider;}catch(e){error.value=e.message;}});
async function preview(){pending.value=true;error.value='';try{plan.value=await libraryRequest(`/${props.bookId}/voice-plans`,{request_id:requestId.value,provider:provider.value,voice:voice.value,text:text.value});requestId.value=crypto.randomUUID();}catch(e){error.value=e.message;}finally{pending.value=false;}}
async function confirm(){pending.value=true;error.value='';try{const result=await libraryRequest(`/${plan.value.id}/confirm`,{},'POST','job-plans');location.hash='jobs/'+result.id;}catch(e){error.value=e.message;}finally{pending.value=false;}}
</script>
<template>
  <section class="mt-4 rounded-xl border border-line bg-surface p-5" aria-labelledby="sample-title"><h2 id="sample-title" class="text-sm font-semibold">Chọn giọng và thử câu ngắn</h2><p class="mt-2 text-xs leading-5 text-muted">Chỉ đọc catalog khi mở form, không nạp model/gọi mạng. Mẫu chạy qua worker và lưu riêng, không tạo chương truyện.</p><p v-if="error" id="voice-error" role="alert" class="mt-3 text-xs">{{error}}</p><div class="mt-4 grid gap-4 sm:grid-cols-2"><label class="grid gap-2 text-xs">Provider<select id="sample-provider" v-model="provider" :disabled="pending" class="rounded border border-line bg-canvas p-2"><option value="vieneu">VieNeu</option><option value="edge-tts">Edge TTS</option><option value="openai">OpenAI</option><option value="piper">Piper</option></select></label><label class="grid gap-2 text-xs">Giọng<select id="sample-voice" v-model="voice" :disabled="pending||!catalog" class="rounded border border-line bg-canvas p-2"><option v-for="item in catalog?.voices||[]" :key="item.id" :value="item.id">{{item.label}}{{item.has_successful_real_sample?' · có mẫu thật đã lưu':''}}</option></select></label></div><p v-if="catalog" id="voice-source" class="mt-3 text-[11px] leading-5 text-muted">Nguồn: {{catalog.source}}. {{catalog.notice||'Danh sách chưa xác minh với dịch vụ/model hiện tại.'}}</p><label class="mt-4 grid gap-2 text-xs">Câu thử (tối đa300 ký tự)<textarea id="sample-text" v-model="text" maxlength="300" rows="3" :disabled="pending" class="rounded border border-line bg-canvas p-3 text-sm"></textarea></label><button id="preview-voice" :disabled="pending||!text.trim()" class="mt-4 rounded border border-line px-3 py-2 text-xs" @click="preview">Xem ảnh hưởng trước khi thử</button><div v-if="plan" id="voice-plan" class="mt-4"><p class="text-xs leading-5">{{plan.plan.notice}}</p><ul v-if="plan.plan.blocked" class="mt-3 text-xs"><li v-for="reason in plan.plan.blocked_reasons" :key="reason">{{reason}}</li></ul><button id="confirm-voice" :disabled="pending||plan.plan.blocked" class="mt-3 rounded-lg bg-brand px-4 py-2 text-xs text-brand-ink disabled:opacity-50" @click="confirm">Xác nhận tạo mẫu giọng</button></div></section>
</template>
